/* ─── Types ───────────────────────────────────────────────────────────────── */
interface LiveData {
  trainName: string;
  trainNo: string;
  currentStation: string;
  nextStation: string;
  delay: number;
  lastUpdated: string;
  lat: number | null;
  lng: number | null;
  speed: number | null;
  source: string;
  destination: string;
  timeline: TimelineStop[];
  activeJourneyDate: string | null;
  statusSummary?: string;
  isRunning?: boolean;
  isCancelled?: boolean;
  coaches?: FormattedCoach[];
  rakeType?: string | null;
  totalCoaches?: number;
}

interface LatLng { lat: number; lng: number; }

interface TimelineStop {
  station: string;
  code: string;
  arrival: string;
  departure: string;
  status: "completed" | "current" | "upcoming";
  station_type?: "TERMINAL" | "MAJOR_JUNCTION" | "MINOR_STATION";
  coordinates?: LatLng | null;
  platform?: string | number | null;
  delay_minutes?: number;
  halt?: number;
}

const getHaltTime = (arr?: string, dep?: string): number => {
  if (!arr || !dep || arr === '--:--' || dep === '--:--') return 0;
  try {
    const [arrH, arrM] = arr.split(':').map(Number);
    const [depH, depM] = dep.split(':').map(Number);
    if (isNaN(arrH) || isNaN(arrM) || isNaN(depH) || isNaN(depM)) return 0;

    let arrMinutes = arrH * 60 + arrM;
    let depMinutes = depH * 60 + depM;

    if (depMinutes < arrMinutes) {
      depMinutes += 24 * 60;
    }

    return depMinutes - arrMinutes;
  } catch {
    return 0;
  }
};

const addMinutesToTime = (timeStr?: string, minutes?: number): string => {
  if (!timeStr || timeStr === '--:--') return 'Unknown';
  if (!minutes || minutes <= 0) return timeStr;
  try {
    const [h, m] = timeStr.split(':').map(Number);
    if (isNaN(h) || isNaN(m)) return timeStr;

    let totalMinutes = h * 60 + m + minutes;
    const finalH = Math.floor(totalMinutes / 60) % 24;
    const finalM = totalMinutes % 60;

    const pad = (n: number) => String(n).padStart(2, '0');
    return `${pad(finalH)}:${pad(finalM)}`;
  } catch {
    return timeStr;
  }
};

/* ─── helpers ─────────────────────────────────────────────────────────────── */
const delayColor = (mins: number, statusSummary?: string, isRunning?: boolean, isFuture?: boolean) => {
  const summary = (statusSummary || '').toLowerCase();
  if (summary.includes('cancel')) {
    return { text: "text-rose-400", bg: "bg-rose-500/10 border-rose-500/20", label: "Cancelled" };
  }
  if (isFuture || summary.includes('scheduled')) {
    return { text: "text-blue-400", bg: "bg-blue-500/10 border-blue-500/20", label: "Scheduled" };
  }
  if (summary.includes('reached destination') || summary.includes('completed')) {
    if (mins > 0) {
      return { text: "text-amber-400", bg: "bg-amber-500/10 border-amber-500/20", label: `Completed (+${mins}m)` };
    }
    return { text: "text-slate-400", bg: "bg-slate-500/10 border-slate-500/20", label: "Completed" };
  }
  if (summary.includes('yet to start')) {
    if (mins > 0) {
      return { text: "text-amber-400", bg: "bg-amber-500/10 border-amber-500/20", label: `Yet to start (+${mins}m)` };
    }
    return { text: "text-blue-400", bg: "bg-blue-500/10 border-blue-500/20", label: "Yet to start" };
  }
  if (!mins || mins <= 0) {
    return { text: "text-emerald-400", bg: "bg-emerald-500/10 border-emerald-500/20", label: "On Time" };
  }
  if (mins <= 15) return { text: "text-yellow-400", bg: "bg-yellow-500/10 border-yellow-500/20", label: `+${mins} min` };
  if (mins <= 60) return { text: "text-orange-400", bg: "bg-orange-500/10 border-orange-500/20", label: `+${mins} min` };
  return { text: "text-red-400", bg: "bg-red-500/10 border-red-500/20", label: `+${Math.floor(mins / 60)}h ${mins % 60}m` };
};



/* ─── "X seconds ago" ticker ─────────────────────────────────────────────── */
function SecondsTicker({ since }: { since: Date }) {
  const [secs, setSecs] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setSecs(Math.floor((Date.now() - since.getTime()) / 1000)), 1000);
    return () => clearInterval(id);
  }, [since]);

  const label = secs < 60 ? `${secs}s ago` : `${Math.floor(secs / 60)}m ago`;
  const color = secs < 15 ? "text-emerald-400" : secs < 60 ? "text-yellow-400" : "text-orange-400";

  return (
    <span className={`font-mono text-xs ${color} tabular-nums`}>
      Last updated: {label}
    </span>
  );
}

/* ─── Progress tracker ────────────────────────────────────────────────────── */
function ProgressTracker({ source, current, destination, timeline }: {
  source: string; current: string; destination: string; timeline: TimelineStop[];
}) {
  const totalStops = Math.max(timeline.length, 3);
  const completedIdx = timeline.findIndex(s => s.status === "current");
  const pct = totalStops > 1 ? Math.round((completedIdx / (totalStops - 1)) * 100) : 0;

  return (
    <div className="bg-card border border-subtle rounded-2xl p-6">
      <h3 className="text-xs font-bold text-muted uppercase tracking-widest mb-5 flex items-center gap-2">
        <Navigation className="w-3.5 h-3.5 text-blue-500 dark:text-blue-400" />
        Journey Progress
      </h3>
      <div className="relative mb-6">
        <div className="h-2 bg-card rounded-full overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-blue-600 to-blue-400 rounded-full transition-[width] duration-[1500ms] ease-in-out"
            style={{ width: `${pct}%` }}
          />
        </div>
        <div className="absolute left-0 -top-1.5 w-5 h-5 rounded-full bg-emerald-500 border-2 border-card" />
        <div
          className="absolute -top-2 w-6 h-6 rounded-full bg-blue-600 border-2 border-card shadow-md flex items-center justify-center transition-[left] duration-[1500ms] ease-in-out z-10"
          style={{ left: `calc(${pct}% - 12px)` }}>
          <span className="absolute -inset-1 rounded-full bg-blue-500/30 animate-ping" />
          <TrainFront className="w-3 h-3 text-white relative z-10" />
        </div>
        <div className="absolute right-0 -top-1.5 w-5 h-5 rounded-full bg-slate-600 border-2 border-card" />
      </div>
      <div className="flex justify-between text-xs">
        <div className="text-left">
          <div className="font-bold text-emerald-400">{source}</div>
          <div className="text-muted text-[10px]">Origin</div>
        </div>
        <div className="text-center">
          <div className="font-bold text-blue-500 dark:text-blue-400">{current}</div>
          <div className="text-muted text-[10px]">Current</div>
        </div>
        <div className="text-right">
          <div className="font-bold text-muted">{destination}</div>
          <div className="text-muted text-[10px]">Destination</div>
        </div>
      </div>
      <div className="mt-4 text-right text-xs text-muted">{pct}% of journey completed</div>
    </div>
  );
}

